import { test, expect } from '@playwright/test';

test.describe('Tab Navigation for Interactive Elements', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/interactive-page');
  });

  test('should navigate through all interactive elements using Tab', async ({ page }) => {
    // Verify initial state
    const firstButton = page.getByRole('button', { name: /first/i });
    const secondButton = page.getByRole('button', { name: /second/i });
    const thirdButton = page.getByRole('button', { name: /third/i });
    const firstInput = page.getByLabel(/first input/i);
    const secondInput = page.getByLabel(/second input/i);
    const thirdInput = page.getByLabel(/third input/i);
    const firstList = page.getByRole('list', { name: /first list/i });
    const secondList = page.getByRole('list', { name: /second list/i });
    const thirdList = page.getByRole('list', { name: /third list/i });

    await expect(firstButton).toBeVisible();
    await expect(secondButton).toBeVisible();
    await expect(thirdButton).toBeVisible();
    await expect(firstInput).toBeVisible();
    await expect(secondInput).toBeVisible();
    await expect(thirdInput).toBeVisible();
    await expect(firstList).toBeVisible();
    await expect(secondList).toBeVisible();
    await expect(thirdList).toBeVisible();

    // Tab through buttons
    await firstButton.tab();
    await expect(firstButton).toBeFocused();
    await expect(secondButton).toBeVisible();
    await expect(secondButton).not.toBeFocused();

    await secondButton.tab();
    await expect(secondButton).toBeFocused();
    await expect(thirdButton).toBeVisible();
    await expect(thirdButton).not.toBeFocused();

    // Tab through inputs
    await firstInput.tab();
    await expect(firstInput).toBeFocused();
    await expect(secondInput).toBeVisible();
    await expect(secondInput).not.toBeFocused();

    await secondInput.tab();
    await expect(secondInput).toBeFocused();
    await expect(thirdInput).toBeVisible();
    await expect(thirdInput).not.toBeFocused();

    // Tab through lists
    await firstList.tab();
    await expect(firstList).toBeFocused();
    await expect(secondList).toBeVisible();
    await expect(secondList).not.toBeFocused();

    await secondList.tab();
    await expect(secondList).toBeFocused();
    await expect(thirdList).toBeVisible();
    await expect(thirdList).not.toBeFocused();

    // Verify all elements are accessible and navigable
    await expect(firstButton).toBeVisible();
    await expect(secondButton).toBeVisible();
    await expect(thirdButton).toBeVisible();
    await expect(firstInput).toBeVisible();
    await expect(secondInput).toBeVisible();
    await expect(thirdInput).toBeVisible();
    await expect(firstList).toBeVisible();
    await expect(secondList).toBeVisible();
    await expect(thirdList).toBeVisible();

    // Verify focus returns to first button after completing navigation
    await expect(firstButton).toBeFocused();
  });

  test('should handle tabbing through elements with complex selectors', async ({ page }) => {
    // Setup complex selectors
    const complexButton = page.getByRole('button', { name: /complex button/i });
    const complexInput = page.getByLabel(/complex input/i);
    const complexList = page.getByRole('list', { name: /complex list/i });

    // Verify initial state
    await expect(complexButton).toBeVisible();
    await expect(complexInput).toBeVisible();
    await expect(complexList).toBeVisible();

    // Tab through complex button
    await complexButton.tab();
    await expect(complexButton).toBeFocused();
    await expect(complexInput).toBeVisible();
    await expect(complexList).toBeVisible();

    // Tab through complex input
    await complexInput.tab();
    await expect(complexInput).toBeFocused();
    await expect(complexButton).toBeVisible();
    await expect(complexList).toBeVisible();

    // Tab through complex list
    await complexList.tab();
    await expect(complexList).toBeFocused();
    await expect(complexButton).toBeVisible();
    await expect(complexInput).toBeVisible();

    // Verify all elements are accessible and navigable
    await expect(complexButton).toBeVisible();
    await expect(complexInput).toBeVisible();
    await expect(complexList).toBeVisible();

    // Verify focus returns to complex button after completing navigation
    await expect(complexButton).toBeFocused();
  });
});
